<script>

import Navbar from "@/components/Navbars/AuthNavbar.vue";
import FooterComponent from "@/components/Footers/Footer.vue";
import FlipCard from "@/components/FlipCard.vue";
//import WordCloudSphere from "@/components/WordCloudSphere.vue";
import LogoCarousel from "@/components/LogoCarousel.vue";
import ContactBlock from "@/components/ContactBlock.vue";
//SEO
import { useHead } from '@unhead/vue';

export default {
  components: {
    Navbar,
    FooterComponent,
    FlipCard,
    //WordCloudSphere,
    LogoCarousel,
    ContactBlock,
  },

  created() {
    const pageTitle = 'EQUAIAR | Ingeniería de datos, bioinformática y software a medida'
    const pageDescription = 'Somos una startup argentina de tecnología conformada por un equipo multidisciplinario de científicos, desarrolladores de software e ingenieros de datos.'

    useHead({
      title: pageTitle,
      meta: [
        { name: 'description', content: pageDescription },
        { property: 'og:type', content: 'website' },
        { property: 'og:title', content: pageTitle },
        { property: 'og:description', content: pageDescription },
        { property: 'og:url', content: 'https://equaiar.com.ar/' },
        { property: 'og:image', content: 'https://equaiar.com.ar/images/fondoLanding.jpg' },
        { name: 'twitter:card', content: 'summary_large_image' },
        { name: 'twitter:title', content: pageTitle },
        { name: 'twitter:description', content: pageDescription },
        { name: 'twitter:image', content: 'https://equaiar.com.ar/images/fondoLanding.jpg' },
      ],
      link: [
        { rel: 'canonical', href: 'https://equaiar.com.ar/' }
      ]
    })
  },

  data() {
    return {
      currentSlide: 0,
      intervalId: null,
      quehacemos: [
        { key: 'analizar', icon: 'fa-magnifying-glass-chart' },
        { key: 'integrar', icon: 'fa-diagram-project' },
        { key: 'procesar', icon: 'fa-gears' },
        { key: 'automatizar', icon: 'fa-arrows-rotate' },
        { key: 'desarrollar', icon: 'fa-code' },
      ],
      logos: [
        { src: "/logos/logo3.png", url: "https://impam.conicet.gov.ar/limra/" },
        { src: "/logos/logo4.png", url: "https://impam.conicet.gov.ar/" },
        { src: "/logos/logo5.png", url: "https://bioinfo.fmed.uba.ar/" },
      ],
    };
  },

  computed: {
    // Los slides se leen reactivamente desde i18n,
    // cambian automáticamente al cambiar de idioma
    slides() {
      return this.$tm('slides');
    },
  },

  mounted() {
    this.startAutoSlide();
  },

  beforeUnmount() {
    clearInterval(this.intervalId);
  },

  methods: {
    nextSlide() {
      this.currentSlide = (this.currentSlide + 1) % this.slides.length;
      this.resetAutoSlide();
    },
    prevSlide() {
      this.currentSlide = (this.currentSlide - 1 + this.slides.length) % this.slides.length;
      this.resetAutoSlide();
    },
    startAutoSlide() {
      this.intervalId = setInterval(() => {
        this.currentSlide = (this.currentSlide + 1) % this.slides.length;
      }, 10000);
    },
    resetAutoSlide() {
      clearInterval(this.intervalId);
      this.startAutoSlide();
    },
    goToAreasDeTrabajo() {
      const el = document.getElementById('areas-de-trabajo');
      if (el) {
        const top = el.getBoundingClientRect().top + window.scrollY - 100;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    }
  },
};
</script>

