<script setup>
import { ref, computed } from 'vue'
//import { ArrowRight } from 'lucide-vue-next'
import { useI18n } from 'vue-i18n'

const { t } = useI18n()

const emit = defineEmits(['submit', 'back'])

const empresa = ref('')
const nombre = ref('')
const rubro = ref('')
const cantidadPCs = ref('')

const attempted = ref(false)

const isValid = computed(() =>
  empresa.value.trim() !== '' &&
  nombre.value.trim() !== '' &&
  rubro.value.trim() !== '' &&
  cantidadPCs.value.trim() !== ''
)

const errors = computed(() => ({
  empresa: attempted.value && empresa.value.trim() === '',
  nombre: attempted.value && nombre.value.trim() === '',
  rubro: attempted.value && rubro.value.trim() === '',
  cantidadPCs: attempted.value && cantidadPCs.value.trim() === '',
}))

function handleSubmit() {
  attempted.value = true
  if (!isValid.value) return

  emit('submit', {
    empresa: empresa.value.trim(),
    nombre: nombre.value.trim(),
    rubro: rubro.value.trim(),
    cantidadPCs: cantidadPCs.value.trim(),
  })
}

function fillExample() {
  empresa.value = t('proTest.form.placeholders.empresa')
  nombre.value = t('proTest.form.placeholders.nombre')
  rubro.value = t('proTest.form.placeholders.rubro')
  cantidadPCs.value = t('proTest.form.placeholders.cantidadPCs')
}

function onKeyDown(e) {
  if (e.key === 'Enter') handleSubmit()
}
</script>

<template>
  <section id="formulario"
    class="min-h-screen flex flex-col justify-center pt-16 pb-16 md:pt-20 md:pb-24 px-4 md:px-8 max-w-2xl mx-auto">


   <h2 class="text-3xl md:text-5xl font-extrabold max-w-3xl mb-6 mx-auto text-center text-blueGray-700 mt-10">
      {{ $t('proTest.form.title') }}
    </h2>
    <p class="text-sm text-center mb-8 text-blueGray-500">
      {{ $t('proTest.form.subtitle') }}
    </p>

    <div @keydown="onKeyDown" class="bg-white rounded-lg shadow-lg p-2 md:p-4 w-full max-w-md mx-auto self-center">

      <div class="mb-6">
        <label class="text-base font-medium block mb-1 text-blueGray-500">{{ $t('proTest.form.labels.empresa') }}</label>
        <input v-model="empresa" :placeholder="$t('proTest.form.placeholders.empresa')"
          class="border-0 px-3 py-2.5 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-base shadow focus:outline-none focus:ring w-full ease-linear transition-all duration-150"
          :class="errors.empresa ? 'ring-2 ring-red-400' : ''" />
        <p v-if="errors.empresa" class="text-xs text-red-500 mt-1">
          {{ $t('proTest.form.errors.required') }}
        </p>
      </div>
      <div class="mb-6">
        <label class="text-base font-medium block mb-1 text-blueGray-500">{{ $t('proTest.form.labels.nombre') }}</label>
        <input v-model="nombre" :placeholder="$t('proTest.form.placeholders.nombre')"
          class="border-0 px-3 py-2.5 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-base shadow focus:outline-none focus:ring w-full ease-linear transition-all duration-150"
          :class="errors.nombre ? 'ring-2 ring-red-400' : ''" />
        <p v-if="errors.nombre" class="text-xs text-red-500 mt-1">
          {{ $t('proTest.form.errors.required') }}
        </p>
      </div>
      <div class="mb-6">
        <label class="text-base font-medium block mb-1 text-blueGray-500">{{ $t('proTest.form.labels.rubro') }}</label>
        <input v-model="rubro" :placeholder="$t('proTest.form.placeholders.rubro')"
          class="border-0 px-3 py-2.5 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-base shadow focus:outline-none focus:ring w-full ease-linear transition-all duration-150"
          :class="errors.rubro ? 'ring-2 ring-red-400' : ''" />
        <p v-if="errors.rubro" class="text-xs text-red-500 mt-1">
          {{ $t('proTest.form.errors.required') }}
        </p>
      </div>
      <div class="mb-6">
        <label class="text-base font-medium block mb-1 text-blueGray-500">
          {{ $t('proTest.form.labels.cantidadPCs') }}
        </label>
        <input v-model="cantidadPCs" :placeholder="$t('proTest.form.placeholders.cantidadPCs')" inputmode="numeric"
          @input="cantidadPCs = cantidadPCs.replace(/[^0-9]/g, '')"
          class="border-0 px-3 py-2.5 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-base shadow focus:outline-none focus:ring w-full ease-linear transition-all duration-150"
          :class="errors.cantidadPCs ? 'ring-2 ring-red-400' : ''" />
        <p v-if="errors.cantidadPCs" class="text-xs text-red-500 mt-1">
          {{ $t('proTest.form.errors.required') }}
        </p>
      </div>

      <div>

        <div class="text-center mt-2">
          <button type="button" @click="fillExample" class="text-base underline text-blueGray-400">
            {{ $t('proTest.form.exampleLink') }}
          </button>
        </div>
      </div>
    </div>
    <div class="flex flex-col items-center mt-6">
      <div class="flex items-center gap-6">
        <button type="button" @click="$emit('back')"
          class="inline-flex items-center gap-2 font-semibold text-base px-6 py-3 rounded-lg shadow-lg bg-teal-500 hover:bg-teal-200 text-white transition">
          {{ $t('proTest.form.back') }}
          
        </button>
        <button type="button" @click="handleSubmit" :disabled="!isValid"
          class="inline-flex items-center gap-2 font-semibold text-base px-6 py-3 rounded-lg shadow-lg transition" :class="isValid
            ? 'bg-teal-500 hover:bg-teal-200 text-white cursor-pointer'
            : 'bg-blueGray-200 text-blueGray-400 cursor-not-allowed'">
          {{ $t('proTest.form.cta') }}
          
        </button>
      </div>
      <p v-if="attempted && !isValid" class="text-xs text-red-500 mt-3 text-center">
        {{ $t('proTest.form.errors.incomplete') }}
      </p>
    </div>



  </section>
</template>