<script setup>
import { computed } from 'vue'
import { ARS_LICENSE_PER_PC_MONTHLY, formatARS } from '../../utils/helpers.js'

const props   = defineProps({ empresa: String, cantidadPCs: String })
const pcs     = computed(() => Number(props.cantidadPCs) || 12)
const monthly = computed(() => pcs.value * ARS_LICENSE_PER_PC_MONTHLY)
const yearly  = computed(() => monthly.value * 12)
const empNom  = computed(() => props.empresa || 'Arqueia Tex')
</script>

<template>
  <div class="w-full max-w-md bg-white rounded-lg shadow-sm p-5">
    <p class="text-xs mb-3 text-blueGray-500">
      {{ $t('proTest.comparisons.cost.mock.solved.header', { empresa: empNom, pcs }) }}
    </p>

    <div class="flex items-end justify-between mb-1">
      <span class="text-xs text-blueGray-500">
        {{ $t('proTest.comparisons.cost.mock.solved.licenseLabel') }}
      </span>
      <span class="text-sm font-semibold text-blueGray-300" style="text-decoration: line-through;">
        ${{ formatARS(monthly) }} {{ $t('proTest.comparisons.cost.mock.solved.perMonth') }}
      </span>
    </div>

    <div class="flex items-end justify-between mb-3">
      <span class="text-xs text-blueGray-500">{{ $t('proTest.comparisons.cost.mock.solved.yearlyLabel') }}</span>
      <span class="text-sm font-semibold text-blueGray-300" style="text-decoration: line-through;">
        ~${{ formatARS(yearly) }}
      </span>
    </div>

    <div class="h-px my-3 bg-blueGray-100" />

    <div class="flex items-end justify-between">
      <span class="text-xs font-medium text-blueGray-700">
        {{ $t('proTest.comparisons.cost.mock.solved.freeLabel') }}
      </span>
      <span class="text-base font-bold text-teal-500">
        {{ $t('proTest.comparisons.cost.mock.solved.freeAmount') }}
      </span>
    </div>

    <p class="pt-3 text-xs text-blueGray-400">
      {{ $t('proTest.comparisons.cost.mock.solved.footer') }}
    </p>
  </div>
</template>